                    data[name]={'returncode':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
                except Exception as exc:data[name]={'error':str(exc)}
            data['sample_seconds']=time.time()-start;stream.write(json.dumps(data)+'\n');stream.flush();stop.wait(5)
