    reg=json.loads((D/'REGISTRATION.json').read_text());load_local_env(R/'.env.local');sett=replace(get_runtime_settings(),base_url=reg['base_url'],model=reg['model'],model_sha256=reg['model_sha256'],tool_disclosure_mode='full',return_token_ids=True,state_transport='native_required',state_profile_id='zero',state_profile_sha256='0'*64)
