            job=ReadOnlyJob(name,reg['task'],str(root/'workspace'),str(root/'execution'),12,600,tool_scope='inspect');v.write_once(root/'JOB.json',job.__dict__);jobs.append(job)
        batch=D/'batches'/f'{mode}-r{rep}';batch.mkdir(parents=True);prep_seconds=time.monotonic()-prepared
        stop=threading.Event();thread=threading.Thread(target=sample,args=(stop,batch/'GPU_SAMPLES.jsonl',reg['resource_scope']['gpu_uuid']),daemon=True);thread.start();start=time.time()
