        print(mode,rep,[(r['id'],r['termination_reason'],r['generation_started']) for r in results],flush=True)
    v.write_once(D/'COMPLETE.json',{'completed':True,'source_unchanged':all(v.file_digest(R/p)==h for p,h in reg['production'].items())})
